'use strict';
/* CP2 interface. The deferred endgame encounter and its unlock system are intentionally absent. */
(function(){
 const CH=JourneyChallenges,AD=JourneyAdvantages;let page=null;
 const title=x=>esc(L(x.en,x.pt)),description=x=>esc(L(x.enDesc,x.ptDesc));
 function eligible(){return S&&!S.training&&!S.tutorialReplay&&!S.meta?.ended;}
 function setup(){page='setup';const pc=CH.profile(),ids=S.pendingChallenges??pc.selected,planned=AD.owned().includes('planned_hand');
  show('<section class="cp2-screen"><div class="eyebrow">'+L('BEFORE THE JOURNEY','ANTES DA JORNADA')+'</div><h2>'+L('Journey Challenges','Desafios da Jornada')+'</h2><div class="cp2-summary"><b>'+ids.length+' '+L('of','de')+' '+pc.available+'</b><span>'+L('Run level','Nível da run')+' '+ids.length+' · '+L('Highest won','Maior vencido')+' '+CH.highestWon()+'</span></div><p class="panel-hint">'+L('Choose any combination up to your available level. The first victory at a new level grants 1 Insignia. Level 0 plays without challenges.','Escolha qualquer combinação até o nível disponível. A primeira vitória em cada nível inédito concede 1 Insígnia. Nível 0 joga sem desafios.')+'</p>'+(planned?'<button class="secondary cp2-planned" data-act="cp2-planned">'+L('Planned Hand: ','Mão Planejada: ')+(S.plannedHandChoice?esc(G.BY[S.plannedHandChoice].name):L('Choose a card','Escolher carta'))+' ›</button>':'')+'<div class="cp2-list">'+CH.LIST.map(c=>'<button class="cp2-entry '+(ids.includes(c.id)?'chosen':'')+'" data-act="cp2-toggle" data-id="'+c.id+'" aria-pressed="'+ids.includes(c.id)+'" '+(!pc.unlocked||!ids.includes(c.id)&&ids.length>=pc.available?'disabled':'')+'><span class="cp2-mark">'+(ids.includes(c.id)?'◆':'◇')+'</span><span><b>'+title(c)+'</b><p>'+description(c)+'</p>'+(pc.completed.includes(c.id)?'<small>✓ '+L('Completed','Concluído')+'</small>':'')+'</span></button>').join('')+'</div></section><div class="training-sticky cp2-footer">'+metaButton('cp2-confirm',L('Begin journey · level ','Começar jornada · nível ')+ids.length,planned&&!S.plannedHandChoice?'disabled':'','primary')+metaButton('cp2-home',L('Main menu','Menu principal'),'','secondary')+'</div>');
 }
 function advantages(){page='advantages';closeModal();const pc=CH.profile(),owned=AD.owned();show('<section class="cp2-screen"><div class="eyebrow">'+L('JOURNEY PREPARATION','PREPARAÇÃO DA JORNADA')+'</div><h2>'+L('Journey Advantages','Vantagens da Jornada')+'</h2><div class="cp2-summary"><b>'+Progress.profile.insignia+' '+L('Insignia','Insígnias')+'</b><span>'+owned.length+'/15</span></div><p class="panel-hint">'+L('Each active advantage uses 1 Insignia. Deactivate to recover it, or reset your selection. Changes apply to your next run.','Cada vantagem ativa usa 1 Insígnia. Desative para recuperá-la ou redistribua todas. Mudanças valem para a próxima run.')+'</p><div class="cp2-list">'+AD.LIST.map(a=>'<article class="cp2-entry"><span><b>'+title(a)+'</b><p>'+description(a)+'</p><button class="'+(owned.includes(a.id)?'secondary':'primary')+'" data-act="cp2-buy" data-id="'+a.id+'" aria-pressed="'+owned.includes(a.id)+'" '+(!pc.unlocked||!owned.includes(a.id)&&Progress.profile.insignia<1?'disabled':'')+'>'+(owned.includes(a.id)?'✓ '+L('Deactivate · recover 1 Insignia','Desativar · recuperar 1 Insígnia'):L('Activate · 1 Insignia','Ativar · 1 Insígnia'))+'</button></span></article>').join('')+'</div></section><div class="training-sticky cp2-footer">'+metaButton('cp2-reset',L('Reset selection','Redistribuir todas'),owned.length?'':'disabled','secondary')+metaButton('cp2-home',L('Back','Voltar'),'','primary')+'</div>');}
 function plannedPicker(){const types=[...new Set(S.cards.filter(c=>!JourneyContent.isCurse(c)).map(c=>c.type))];journeyPanel(L('Planned Hand','Mão Planejada'),'<p class="panel-hint">'+L('An existing copy starts in your hand in confrontations 1, 3, 5…','Uma cópia existente começa na mão nos confrontos 1, 3, 5…')+'</p><div class="content-card-grid">'+types.map(type=>cardFace({uid:type,type,level:0},'cp2-pick')).join('')+'</div>',metaButton('close',L('Back','Voltar')));}
 const baseHome=metaHomeButtons;metaHomeButtons=function(){return baseHome()+(CH.profile().unlocked?metaButton('cp2-advantages',L('Journey Advantages','Vantagens da Jornada')):'');};
 function runModifiers(){journeyPanel(L('This journey','Nesta jornada'),'<h3>'+L('Challenges','Desafios')+' · '+(S.challenges?.length||0)+'</h3>'+((S.challenges||[]).map(id=>'<article class="cp2-modifier"><b>'+title(CH.BY[id])+'</b><p>'+description(CH.BY[id])+'</p></article>').join('')||'<p>'+L('No active challenges.','Sem desafios ativos.')+'</p>')+'<h3>'+L('Advantages','Vantagens')+' · '+(S.adv?.owned?.length||0)+'</h3>'+((S.adv?.owned||[]).map(id=>'<article class="cp2-modifier"><b>'+title(AD.BY[id])+'</b><p>'+description(AD.BY[id])+'</p></article>').join('')||'<p>'+L('No active advantages.','Sem vantagens ativas.')+'</p>'),metaButton('close',L('Back','Voltar'),'','primary'));}
 const baseMenu=journeyMenu;journeyMenu=function(){baseMenu();if(eligible()&&CH.profile().unlocked&&S.challenges)document.querySelector('#overlay .stack')?.insertAdjacentHTML('afterbegin',metaButton('cp2-modifiers',L('This run: advantages & challenges','Nesta run: vantagens e desafios')));};
 const baseRender=render;render=function(){page=null;if(eligible()&&S.phase==='map'&&JourneyActs.act(S)===1&&!S.route.length&&!S.challenges){if(!S.runSetupConfirmed&&CH.profile().unlocked){setup();save();return;}CH.start(S);}return baseRender();};
 const baseRefresh=refreshMeta;refreshMeta=function(){if(page==='setup'&&document.querySelector('.cp2-screen'))return setup();if(page==='advantages'&&document.querySelector('.cp2-screen'))return advantages();return baseRefresh();};
 const basePrep=prep;prep=function(){basePrep();const button=document.querySelector('[data-act="refresh-hand"]');if(button&&AD.flexLeft(S)>0){button.disabled=!S.hand.length;button.innerHTML='↻ '+L('Free','Grátis');button.setAttribute('aria-label',L('Refresh hand · free','Reciclar mão · grátis'));}};
 function rerollFooter(){if(AD.canReroll(S)){const footer=document.createElement('div');footer.className='screen-footer cp2-footer';footer.innerHTML=metaButton('cp2-reroll',L('Reroll relics · free','Renovar relíquias · grátis'),'','primary');document.querySelector('#app').append(footer);}}
 const baseRelic=relicView;relicView=function(){baseRelic();rerollFooter();};
 const baseEventReward=eventRewardView;eventRewardView=function(){baseEventReward();rerollFooter();};
 const baseResult=resultView;resultView=function(){baseResult();if(!S?.training&&S.meta?.ended&&CH.profile().unlocked){const panel=document.createElement('section');panel.className='cp2-result';panel.innerHTML='<h3>'+L('Journey Challenges','Desafios da Jornada')+'</h3>'+(S.meta.reason==='victory'?'<p>'+L('Level won: ','Nível vencido: ')+(S.meta.challengeLevel||0)+' · '+L('Insignia earned: ','Insígnias recebidas: ')+(S.meta.insignia||0)+'</p>'+(S.meta.challengesUnlocked?'<p>'+L('Challenges unlocked! Level 1 is now available.','Desafios liberados! Nível 1 disponível.')+'</p>':'')+(S.meta.completedChallenges?.length?'<ul>'+S.meta.completedChallenges.map(id=>'<li>✓ '+title(CH.BY[id])+'</li>').join('')+'</ul>':''):'<p>'+L('No Insignia earned. Banked tree XP is preserved.','Nenhuma Insígnia recebida. O XP guardado da árvore foi preservado.')+'</p>');document.querySelector('#screen-content').append(panel);const actions=document.querySelector('.result-navigation .stack');if(actions){const footer=document.createElement('div');footer.className='screen-footer cp2-footer';footer.append(...actions.children);document.querySelector('#app').append(footer);actions.remove();}}};
 const guard=JourneyTraining.guard;JourneyTraining.guard=function(e){const el=e.target.closest?.('[data-act]'),d=el?.dataset;if(!d?.act.startsWith('cp2-')){const result=guard(e);if(e.type==='click'&&d?.act==='content-picker'&&AD.canReroll(S,d.key)){document.querySelector('.journey-panel-footer')?.insertAdjacentHTML('afterbegin',metaButton('cp2-reroll',L('Reroll · free','Renovar · grátis'),'data-key="'+d.key+'"','primary'));}return result;}if(e.type!=='click'&&!(e.type==='keydown'&&['Enter',' '].includes(e.key)))return guard(e);e.preventDefault();e.stopImmediatePropagation();if(el.disabled)return true;
  if(d.act==='cp2-modifiers')runModifiers();else if(d.act==='cp2-advantages')advantages();else if(d.act==='cp2-home'){page=null;closeModal();home();}else if(d.act==='cp2-toggle'){const ids=S.pendingChallenges??[...CH.profile().selected],on=ids.includes(d.id);if(CH.BY[d.id]&&(on||ids.length<CH.profile().available)){S.pendingChallenges=on?ids.filter(id=>id!==d.id):[...ids,d.id];save();setup();}}else if(d.act==='cp2-confirm'){const ids=S.pendingChallenges??CH.profile().selected;if(!AD.owned().includes('planned_hand')||G.BY[S.plannedHandChoice]){if(CH.select(ids)){S.pendingChallenges=[...ids];S.runSetupConfirmed=true;CH.start(S);page=null;save();render();}}}else if(d.act==='cp2-planned')plannedPicker();else if(d.act==='cp2-pick'){if(S.cards.some(c=>c.type===d.id)){S.plannedHandChoice=d.id;closeModal();save();setup();}}else if(d.act==='cp2-buy'){if(AD.owned().includes(d.id)?AD.deactivate(d.id):AD.buy(d.id)){save();advantages();}}else if(d.act==='cp2-reset'){if(AD.reset()){save();advantages();}}else if(d.act==='cp2-reroll'){if(AD.rerollRelic(S,d.key)){save();if(d.key){closeModal();document.querySelector('[data-act="content-picker"][data-key="'+d.key+'"]')?.click();}else render();}}return true;
 };
})();
